                "horzJS": "const amplitude = $gameScreen._shakePower * 0.75;\nconst variance = $gameScreen._shakeSpeed * 0.6;\nconst fade = Math.min($gameScreen._shakeDuration, 30) / 2;\nthis.x += Math.round(Math.randomInt(amplitude) - Math.randomInt(variance)) * fade;",
